var katexMathtexScriptType=(()=>{var o=globalThis.katex;var l=document.body.getElementsByTagName("script");l=Array.prototype.slice.call(l);l.forEach(t=>{if(t.type&&t.type.match(/math\/tex/i)){let a=t.type.match(/mode\s*=\s*display(;|\s|\n|$)/)!=null,e=document.createElement(a?"div":"span");e.setAttribute("class",a?"equation":"inline-equation");try{o.render(t.text,e,{displayMode:a})}catch{e.textContent=t.text}t.parentNode.replaceChild(e,t)}});})();
